package br.com.sussmartcare.clinicalquery.domain; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="patient_profile_views") public class PatientProfileView {@Id private UUID patientId;@Column(nullable=false)private String fullName;private LocalDate birthDate;@Column(nullable=false)private String identityStatus;private UUID mergedIntoPatientId;@Column(nullable=false)private Instant updatedAt;protected PatientProfileView(){}public PatientProfileView(UUID id,String name,LocalDate birth,String status,UUID merged,Instant updated){patientId=id;fullName=name;birthDate=birth;identityStatus=status;mergedIntoPatientId=merged;updatedAt=updated;}public void update(String name,LocalDate birth,String status,UUID merged,Instant updated){fullName=name;birthDate=birth;identityStatus=status;mergedIntoPatientId=merged;updatedAt=updated;}public UUID getPatientId(){return patientId;}public String getFullName(){return fullName;}public LocalDate getBirthDate(){return birthDate;}public String getIdentityStatus(){return identityStatus;}public UUID getMergedIntoPatientId(){return mergedIntoPatientId;}}
